custom_css:
/* Base */
body {
  background: #080a0c;
  -webkit-font-smoothing: antialiased;
}

/* Noise overlay */
body::before {
  content: '';
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  opacity: 0.025;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
  background-size: 200px;
}

/* Grid line hero background — apply class .halo-grid to any section */
.halo-grid {
  background-image:
    linear-gradient(rgba(0,210,180,0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0,210,180,0.04) 1px, transparent 1px);
  background-size: 60px 60px;
}

/* Teal ambient glow — apply class .halo-glow to any section */
.halo-glow::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 70% 50% at 50% 30%, rgba(0,210,180,0.07) 0%, transparent 60%);
  pointer-events: none;
  z-index: 0;
}

/* Halo card — apply class .halo-card to any inner section or widget wrapper */
.halo-card {
  background: #111518;
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 8px;
  transition: border-color 0.25s, transform 0.25s;
}

.halo-card:hover {
  border-color: rgba(0,210,180,0.3);
  transform: translateY(-3px);
}

/* Teal top-line card — apply class .halo-card-line */
.halo-card-line {
  background: #141820;
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 0;
  position: relative;
  overflow: hidden;
  transition: background 0.2s;
}

.halo-card-line::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 2px;
  background: #00d2b4;
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.3s ease;
  z-index: 1;
}

.halo-card-line:hover::before { transform: scaleX(1); }
.halo-card-line:hover { background: rgba(20,24,32,0.95); }

/* Glowing dot — add an HTML widget with <div class="halo-dot"></div> */
.halo-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #00d2b4;
  box-shadow: 0 0 10px rgba(0,210,180,0.6);
  display: inline-block;
}

.halo-dot-pulse {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #00d2b4;
  animation: halo-pulse 2s ease-in-out infinite;
  display: inline-block;
}

@keyframes halo-pulse {
  0%, 100% { opacity: 1; transform: scale(1); box-shadow: 0 0 8px rgba(0,210,180,0.5); }
  50% { opacity: 0.5; transform: scale(0.8); box-shadow: 0 0 4px rgba(0,210,180,0.2); }
}

/* Badge pill — apply class .halo-badge to a button or text widget */
.halo-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 16px;
  border: 1px solid rgba(0,210,180,0.3);
  border-radius: 100px;
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #00d2b4;
  background: rgba(0,210,180,0.06);
}

/* Signal/tag chip */
.halo-tag {
  font-size: 11px;
  padding: 4px 10px;
  border: 1px solid rgba(0,210,180,0.2);
  color: rgba(0,210,180,0.7);
  letter-spacing: 0.04em;
  display: inline-block;
  border-radius: 3px;
}

/* Section eyebrow */
.halo-eyebrow {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: #00d2b4;
  display: block;
  margin-bottom: 16px;
  font-family: 'Syne', sans-serif;
}

/* Primary button */
.halo-btn {
  background: #00d2b4 !important;
  color: #080a0c !important;
  font-family: 'Syne', sans-serif !important;
  font-size: 13px !important;
  font-weight: 600 !important;
  letter-spacing: 0.06em !important;
  text-transform: uppercase !important;
  border-radius: 4px !important;
  padding: 13px 28px !important;
  border: none !important;
  transition: opacity 0.2s !important;
}

.halo-btn:hover { opacity: 0.85 !important; }

/* Ghost button */
.halo-btn-ghost {
  background: transparent !important;
  color: #f4f6f8 !important;
  font-family: 'Syne', sans-serif !important;
  font-size: 13px !important;
  font-weight: 500 !important;
  letter-spacing: 0.04em !important;
  border: 1px solid rgba(255,255,255,0.15) !important;
  border-radius: 4px !important;
  padding: 13px 28px !important;
  transition: border-color 0.2s !important;
}

.halo-btn-ghost:hover { border-color: rgba(255,255,255,0.4) !important; }

/* Fade-up entrance animation */
@keyframes halo-fadeup {
  from { opacity: 0; transform: translateY(20px); }
  to   { opacity: 1; transform: translateY(0); }
}

.halo-animate {
  animation: halo-fadeup 0.7s ease both;
}

.halo-animate-1 { animation-delay: 0.1s; }
.halo-animate-2 { animation-delay: 0.2s; }
.halo-animate-3 { animation-delay: 0.3s; }
.halo-animate-4 { animation-delay: 0.4s; }
